/* @lc app=leetcode id=2281 lang=kotlin */
class Solution { fun totalStrength(A: IntArray): Int = 1000000007L.let { M -> LongArray(A.size + 1).also { p -> A.indices.forEach { i -> (p[i] + A[i]).let { p[i+1] = it % M } } }.let { p -> LongArray(p.size + 1).also { pp -> p.indices.forEach { i -> (pp[i] + p[i]).let { pp[i+1] = it % M } } }.let { pp -> java.util.ArrayDeque<Int>().also { s -> s.push(-1) }.let { s -> (0..A.size).fold(0L) { total, r -> (total + generateSequence { if (s.peek() != -1 && (r == A.size || A[s.peek()] >= A[r])) s.pop() else null }.map { i -> s.peek().let { l -> (A[i].toLong() * (((i - l).toLong() * (pp[r + 1] - pp[i + 1] + M) % M - (r - i).toLong() * (pp[i + 1] - pp[l + 1] + M) % M + M) % M)) % M } }.sum()).also { s.push(r) } }.let { (it % M).toInt() } } } } }